package dev.padbridge.app;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.*;
import java.io.*;
import java.util.*;

public final class CoreTest {
    private static String caps(String name){return "add device 1: /dev/input/event9\n  name: \""+name+"\"\n  events:\n    KEY (0001): 0130 0131 0133 0134 0136 0137 013a 013b 013d 013e\n    ABS (0003): 0000 : value 127, min 0, max 255, fuzz 0, flat 15\n    0001 : value 127, min 0, max 255\n    0002 : value 127, min 0, max 255\n    0005 : value 127, min 0, max 255\n    0009 : value 0, min 0, max 255\n    000a : value 0, min 0, max 255\n    0010 : value 0, min -1, max 1\n    0011 : value 0, min -1, max 1\n  input props:\n    <none>\n";}
    private static int word(byte[] data,int offset){return ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN).getShort(offset)&65535;}
    @Test public void detectsCapabilitiesAcrossBrands(){for(String name:new String[]{"8BitDo Ultimate 2C Wireless","GameSir Controller","Generic USB Gamepad","DualSense Wireless Controller"})assertEquals(1,DeviceCatalog.parse(caps(name)).size());}
    @Test public void rejectsTouchscreenAndOwnOutput(){assertEquals(0,DeviceCatalog.parse(caps("Touch device").replace("<none>","INPUT_PROP_DIRECT")).size());assertEquals(0,DeviceCatalog.parse(caps("Bad device").replace("0130 0131","014a 0131")).size());assertEquals(0,DeviceCatalog.parse(caps(HidCodec.NAME).replace("  events:","  location: \"padbridge:virtual\"\n  events:")).size());assertEquals(1,DeviceCatalog.parse(caps(HidCodec.NAME)).size());}
    @Test public void rejectsKeyboardAndSingleStick(){assertEquals(0,DeviceCatalog.parse(caps("Keyboard").replace("0130 0131 0133 0134 0136 0137 013a 013b 013d 013e","001e 0030 002e")).size());assertEquals(0,DeviceCatalog.parse(caps("Single stick").replace("0005 : value","0006 : value")).size());}
    @Test public void fingerprintSurvivesReconnectAndMovement(){String a=DeviceCatalog.parse(caps("Generic USB")).get(0).signature;String b=DeviceCatalog.parse(caps("Generic USB").replace("event9","event12").replace("value 127","value 255")).get(0).signature;assertEquals(a,b);assertNotEquals(a,DeviceCatalog.parse(caps("Another model")).get(0).signature);}
    @Test public void detectsMultiplePads(){assertEquals(2,DeviceCatalog.parse(caps("First")+caps("Second").replace("device 1","device 2").replace("event9","event10")).size());}
    @Test public void hidPacketIsCorrect(){byte[] create=HidCodec.create();ByteBuffer b=ByteBuffer.wrap(create).order(ByteOrder.LITTLE_ENDIAN);assertEquals(11,b.getInt());assertEquals(0x045e,b.getInt(264));assertEquals(0x02e0,b.getInt(268));assertEquals(HidCodec.DESCRIPTOR.length,word(create,260));assertEquals(15,HidCodec.neutral().length);assertEquals(12,ByteBuffer.wrap(HidCodec.input(HidCodec.neutral())).order(ByteOrder.LITTLE_ENDIAN).getInt());}
    @Test public void forwardsSticksTriggersButtonsAndHat(){PadState p=new PadState(caps("Generic"),new PadMapping());p.event(3,0,255);p.event(3,1,0);p.event(3,2,0);p.event(3,5,255);p.event(3,10,255);p.event(3,9,128);p.event(1,304,1);p.event(3,16,-1);p.event(3,17,-1);byte[] r=p.report();assertEquals(65535,word(r,0));assertEquals(0,word(r,2));assertEquals(0,word(r,4));assertEquals(65535,word(r,6));assertEquals(32767,word(r,8));assertEquals(16448,word(r,10));assertEquals(1,word(r,12));assertEquals(8,r[14]);p.event(1,304,0);assertEquals(0,word(p.report(),12));}
    @Test public void deadzoneSuppressesCenterNoiseAndInversionWorks(){PadMapping m=new PadMapping();PadState p=new PadState(caps("Generic"),m);assertEquals(32768,word(p.report(),0));p.event(3,0,130);assertEquals(32768,word(p.report(),0));m.inverted[0]=true;p.event(3,0,255);assertEquals(0,word(p.report(),0));}
    @Test public void customButtonAssignmentReplacesDefault(){PadMapping m=new PadMapping();Map<Integer,Integer> custom=new HashMap<>();custom.put(306,2);custom.put(307,3);m.applyButtons(custom);PadState p=new PadState(caps("Generic"),m);p.event(1,306,1);assertEquals(4,word(p.report(),12));p.event(1,306,0);p.event(1,307,1);assertEquals(8,word(p.report(),12));}
    @Test public void digitalTriggersWorkWithoutAnalogAxes(){String c=caps("Switch like").replace("0009 : value","000b : value").replace("000a : value","000c : value");PadState p=new PadState(c,new PadMapping());p.event(1,312,1);p.event(1,313,1);assertEquals(32767,word(p.report(),8));assertEquals(32767,word(p.report(),10));}
    @Test public void conflictingDigitalTriggerDoesNotFire(){PadMapping m=new PadMapping();m.lt=-2;Map<Integer,Integer> remap=new HashMap<>();remap.put(312,8);m.applyButtons(remap);PadState p=new PadState(caps("Generic"),m);p.event(1,312,1);assertEquals(0,word(p.report(),8));assertEquals(256,word(p.report(),12));}
    @Test public void explicitDigitalTriggerOverridesAnalogAndDefaultButton(){PadMapping m=new PadMapping();m.applyDigital(Collections.singletonMap(0,304));PadState p=new PadState(caps("Generic"),m);assertEquals(-2,m.lt);p.event(1,304,1);assertEquals(32767,word(p.report(),8));assertEquals(0,word(p.report(),12));p.event(1,304,0);assertEquals(0,word(p.report(),8));}
    @Test public void explicitDigitalDpadRemovesDefaultMainButton(){PadMapping m=new PadMapping();m.applyDigital(Collections.singletonMap(2,304));PadState p=new PadState(caps("Generic"),m);p.event(1,304,1);assertEquals(1,p.report()[14]);assertEquals(0,word(p.report(),12));}
    @Test public void explicitTriggerTakesOwnershipOfDefaultDpad(){PadMapping m=new PadMapping();m.applyDigital(Collections.singletonMap(0,544));PadState p=new PadState(caps("Generic"),m);p.event(1,544,1);assertEquals(32767,word(p.report(),8));assertEquals(0,p.report()[14]);assertEquals(-1,m.up);}
    @Test public void latestDigitalAssignmentWins(){PadMapping m=new PadMapping();m.applyDigital(Collections.singletonMap(2,304));m.applyDigital(Collections.singletonMap(4,304));PadState p=new PadState(caps("Generic"),m);p.event(1,304,1);assertEquals(7,p.report()[14]);assertEquals(0,word(p.report(),12));assertEquals(-1,m.up);}
    @Test public void mainAssignmentReclaimsExplicitDigitalButton(){PadMapping m=new PadMapping();m.applyDigital(Collections.singletonMap(2,304));m.applyButtons(Collections.singletonMap(304,0));PadState p=new PadState(caps("Generic"),m);p.event(1,304,1);assertEquals(1,word(p.report(),12));assertEquals(0,p.report()[14]);}
    @Test public void mainAssignmentReclaimsDefaultDpadButton(){PadMapping m=new PadMapping();m.applyButtons(Collections.singletonMap(544,0));PadState p=new PadState(caps("Generic"),m);p.event(1,544,1);assertEquals(1,word(p.report(),12));assertEquals(0,p.report()[14]);}
    @Test public void duplicateDigitalAssignmentsAreRejectedBeforeMutation(){PadMapping m=new PadMapping();Map<Integer,Integer> roles=new HashMap<>();roles.put(2,304);roles.put(4,304);try{m.applyDigital(roles);fail();}catch(IllegalArgumentException expected){}assertEquals(Integer.valueOf(0),m.buttons.get(304));assertEquals(544,m.up);}
    @Test public void multipleDisabledDigitalRolesAreValid(){PadMapping m=new PadMapping();Map<Integer,Integer> roles=new HashMap<>();roles.put(0,-1);roles.put(1,-1);roles.put(2,-1);m.applyDigital(roles);new PadState(caps("Generic"),m);assertEquals(-1,m.ltButton);assertEquals(-1,m.rtButton);assertEquals(-1,m.up);}
    @Test(expected=IllegalArgumentException.class) public void rejectsUnknownDigitalRole(){PadMapping.validateDigitalAssignments(Collections.singletonMap(6,304));}
    @Test(expected=IllegalArgumentException.class) public void rejectsDuplicateMainOutputs(){PadMapping m=new PadMapping();Map<Integer,Integer> buttons=new HashMap<>();buttons.put(304,0);buttons.put(305,0);m.applyButtons(buttons);}
    @Test public void swappingDigitalDirectionsDoesNotDependOnMapOrder(){PadMapping m=new PadMapping();Map<Integer,Integer> roles=new LinkedHashMap<>();roles.put(2,545);roles.put(3,544);m.applyDigital(roles);PadState p=new PadState(caps("Generic"),m);p.event(1,544,1);assertEquals(5,p.report()[14]);p.event(1,544,0);p.event(1,545,1);assertEquals(1,p.report()[14]);}
    @Test public void signedRangesAndCustomAxesWork(){String c=caps("Generic").replace("min 0, max 255","min -32768, max 32767");PadMapping m=new PadMapping();m.lx=2;m.rx=0;PadState p=new PadState(c,m);p.event(3,2,32767);p.event(3,0,-32768);assertEquals(65535,word(p.report(),0));assertEquals(0,word(p.report(),4));}
    @Test(expected=IllegalArgumentException.class) public void rejectsDuplicateStickAxes(){PadMapping m=new PadMapping();m.rx=0;m.ry=5;new PadState(caps("Generic"),m);}
    @Test(expected=IllegalArgumentException.class) public void rejectsInvalidDeadzone(){PadMapping m=new PadMapping();m.deadzone=Double.NaN;new PadState(caps("Generic"),m);}
    @Test public void detectsDroppedFrames(){PadState p=new PadState(caps("Generic"),new PadMapping());p.event(0,3,0);assertTrue(p.isDropped());}
    @Test public void opposingDigitalDpadReturnsNeutral(){PadMapping m=new PadMapping();PadState p=new PadState(caps("Generic"),m);p.event(1,544,1);assertEquals(1,p.report()[14]);p.event(1,545,1);assertEquals(0,p.report()[14]);p.event(1,544,0);assertEquals(5,p.report()[14]);}
    @Test public void allHatDirections(){int[][] values={{0,0,0},{0,-1,1},{1,-1,2},{1,0,3},{1,1,4},{0,1,5},{-1,1,6},{-1,0,7},{-1,-1,8}};for(int[] v:values)assertEquals(v[2],HidCodec.hat(v[0],v[1]));}
    @Test public void boundedIpcRejectsOversizedHandshake()throws Exception{assertEquals("token",Ipc.line(new StringReader("token\nnext"),64));assertNull(Ipc.line(new StringReader(""),64));try{Ipc.line(new StringReader(String.join("",Collections.nCopies(65,"x"))),64);fail();}catch(IOException expected){}}
}
